'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const icon = name => `<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialNodes = () => [
  {id:'edge-a',role:'Primary ingress',profile:'REALITY / TCP',latency:42,version:'1.12.0'},
  {id:'edge-b',role:'Secondary ingress',profile:'TLS / TCP',latency:null,version:'1.11.2'},
  {id:'relay-a',role:'Proxy',profile:'REALITY / TCP',latency:68,version:'1.12.0'},
  {id:'reserve-a',role:'Standby',profile:'REALITY / TCP',latency:57,version:'1.12.0'}
];
const initialUsers = () => [
  {name:'alice',quota:'300 GB',expiry:'28 days left',delivery:'published'},
  {name:'bob',quota:'300 GB',expiry:'No expiry',delivery:'published'},
  {name:'support',quota:'50 GB',expiry:'7 days left',delivery:'stale'},
  {name:'monitor',quota:'5 GB',expiry:'No expiry',delivery:'published'}
];
const initialJobs = () => [{title:'Published subscription for alice',detail:'Current profiles delivered through the existing URL.',id:'chg-041',kind:'publish'},{title:'Configuration snapshot saved',detail:'Checksum and archive contents verified.',id:'chg-040',kind:'backup'}];
const state = {view:'overview',nodes:initialNodes(),users:initialUsers(),userCount:24,fixed:false,vantage:'local',filter:'all',search:'',checking:false,checkAge:'2 min ago',jobs:initialJobs()};
let pendingPlan = null, wizard = {}, running = false;
const navItems = [{id:'overview',label:'Overview',icon:'grid'},{id:'servers',label:'Servers',icon:'server'},{id:'access',label:'Access',icon:'users'},{id:'checks',label:'Checks',icon:'pulse'},{id:'changes',label:'Changes',icon:'history'},{id:'backups',label:'Recovery',icon:'shield'}];
const bad = node => node.id === 'edge-b' && !state.fixed && state.vantage === 'local';
const localBad = node => node.id === 'edge-b' && !state.fixed;
const pill = (text, type='neutral') => `<span class="pill ${type}">${text}</span>`;
const main = $('#main'), modal = $('#modal'), drawer = $('#drawer');
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),3100); }
function nav() { $('#navigation').innerHTML=navItems.map(n=>`<a href="#${n.id}" class="nav-item ${state.view===n.id?'active':''}" ${state.view===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span>${n.id==='checks'&&!state.fixed&&state.nodes.some(n=>n.id==='edge-b')?'<b class="nav-count">1</b>':''}</a>`).join(''); $('#page-label').textContent=navItems.find(n=>n.id===state.view)?.label || 'Overview'; }
function pageHead(eyebrow,title,description,actions='') { return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`; }
const checkButton = () => `<button class="btn" data-act="run-checks" ${state.checking||!state.nodes.length?'disabled':''}>${icon('pulse')}${state.checking?'Checking…':'Check access'}</button>`;
const addButton = () => `<button class="btn primary" data-act="add-server">${icon('plus')}Add server</button>`;
function nodeRows(nodes) { return nodes.length? nodes.map(n=>`<tr class="clickable" data-act="node" data-id="${esc(n.id)}" tabindex="0" aria-label="Open server ${esc(n.id)}"><td><div class="server-cell"><span class="server-symbol">${icon('server')}</span><span><strong>${esc(n.id)}</strong><small>${esc(n.role)}</small></span></div></td><td><span class="mono muted">${esc(n.profile)}</span></td><td><span class="checkmark">${icon('check')}Running</span></td><td>${localBad(n)?pill('HTTPS failed','warn'):pill(`${n.latency||49} ms · HTTP 200`,'ok')}</td><td class="mono quiet">${esc(n.version)}</td><td>${icon('chevron')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No servers match this search.</td></tr>'; }
function nodeTable(nodes) { return `<div class="table-wrap"><table><thead><tr><th>Server</th><th>Profile</th><th>Services</th><th>Traffic from this device</th><th>Agent</th><th><span class="visually-hidden">Details</span></th></tr></thead><tbody id="node-rows">${nodeRows(nodes)}</tbody></table></div>`; }
function renderOverview() {
  if(!state.nodes.length) { main.innerHTML=pageHead('YOUR FIRST FLEET','From a server to a working connection.','Connect your VPS. Set up Xray, deliver access and verify the result in one guided flow.')+`<div class="panel" style="padding:42px;max-width:850px"><div class="eyebrow">FOUR CLEAR STEPS</div><h2 style="font-size:24px;letter-spacing:-.7px">Your fleet starts here.</h2><div class="detail-grid" style="margin:28px 0">${['01 · Connect a server','02 · Check and configure','03 · Grant access','04 · Verify traffic'].map(s=>`<div class="detail-tile"><strong style="font-size:13px">${s}</strong></div>`).join('')}</div>${addButton()}<p class="help-line">An existing CLI workspace can be opened when starting the desktop app.</p></div>`; return; }
  const failures=state.nodes.filter(localBad).length;
  main.innerHTML=pageHead('FLEET OVERVIEW',failures?'Your fleet is running.<br>One route needs attention.':'Access verified.<br>Your fleet, under control.',failures?'Services respond on every node. A traffic check found an issue on the secondary ingress.':'The latest HTTPS checks from this device passed on every node.',checkButton()+addButton())+
  `<section class="stats" aria-label="Fleet summary"><div class="stat"><div class="stat-label">${icon('server')}Services running</div><div class="stat-value">${state.nodes.length}<span> / ${state.nodes.length}</span></div><div class="stat-note good">All agents reachable</div></div><div class="stat"><div class="stat-label">${icon('pulse')}Access verified</div><div class="stat-value">${state.nodes.length-failures}<span> / ${state.nodes.length}</span></div><div class="stat-note ${failures?'warn':'good'}">${failures?'One route failed HTTPS':'HTTPS / TCP · all nodes'}</div></div><div class="stat"><div class="stat-label">${icon('users')}Users</div><div class="stat-value">${state.userCount}</div><div class="stat-note">Across all enabled servers</div></div><div class="stat"><div class="stat-label">${icon('shield')}Latest snapshot</div><div class="stat-value">15 <span>min ago</span></div><div class="stat-note good">Integrity verified</div></div></section>
  <div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>See the route. Know the result.</h2><p>HTTPS through each ingress · from this device</p></div>${pill('Sample measurements','blue')}</div><div class="route-grid"><div class="origin"><span class="origin-icon">${icon('terminal')}</span><span>This device<br><strong>Tunnel check</strong></span></div>${state.nodes.slice(0,4).map(n=>`<span class="route-line incoming"></span><button class="route-node" data-act="node" data-id="${esc(n.id)}"><i class="dot ok"></i><span class="node-name">${esc(n.id)}</span><span class="tiny">${n.profile.startsWith('TLS')?'TLS':'REALITY'}</span></button><span class="route-line"></span><span class="endpoint ${localBad(n)?'warn':'ok'}">${localBad(n)?'No HTTPS':'HTTP 200'}<span>${localBad(n)?'!':`${n.latency||49} ms`}</span></span>`).join('')}</div><div class="history-strip"><div class="strip-label"><span>LAST 24 HOURS</span><span>${state.checkAge}</span></div><div class="bars" aria-label="Sample checks over the last 24 hours">${Array.from({length:42},(_,i)=>`<span class="bar ${failures&&i>34&&i<40?'warn':''}" title="${failures&&i>34&&i<40?'Traffic needed attention':'HTTPS reachable'}"></span>`).join('')}</div></div></section>
  <aside class="panel attention ${failures?'':'fixed'}"><span class="attention-icon">${icon(failures?'alert':'check')}</span><div class="overline">${failures?'NEEDS YOUR ATTENTION':'RESULT VERIFIED'}</div><h2>${failures?'edge-b responds.<br>But access is failing.':'Every ingress has<br>a verified result.'}</h2><p>${failures?'SSH and Xray respond. Native probe and checker could not complete HTTPS. The cause still needs confirmation.':'Services and HTTPS were checked separately. Users and configuration were preserved after the last change.'}</p><div class="micro">${failures?'First the evidence. Then a change plan.':'UDP and client application imports are checked separately.'}</div><button class="btn" data-act="${failures?'incident':'goto-changes'}">${failures?'Investigate issue':'Open change history'}${icon('arrow')}</button></aside></div>
  <section class="panel"><div class="table-head"><h2>Servers <span class="secondary">${state.nodes.length} nodes in the fleet</span></h2><button class="text-link" data-act="goto-servers">All servers ${icon('arrow')}</button></div>${nodeTable(state.nodes.slice(0,4))}</section>`;
}
function filteredNodes() { return state.nodes.filter(n=>(state.filter!=='issues'||localBad(n))&&n.id.toLowerCase().includes(state.search.toLowerCase())); }
function renderServers() { main.innerHTML=pageHead('INFRASTRUCTURE','Your servers. One working fleet.','Service health and working traffic are shown separately.',addButton())+`<div class="toolbar"><div class="filter-list"><button class="filter ${state.filter==='all'?'active':''}" data-act="filter" data-id="all">All servers · ${state.nodes.length}</button><button class="filter ${state.filter==='issues'?'active':''}" data-act="filter" data-id="issues">Need attention · ${state.nodes.filter(localBad).length}</button></div><input class="input-search" id="node-search" placeholder="Search by name…" aria-label="Find a server" value="${esc(state.search)}"></div><section class="panel">${nodeTable(filteredNodes())}</section><p class="help-line">Every configuration change starts with a plan. Review affected nodes, users and recovery before applying it.</p>`; }
function renderAccess() { main.innerHTML=pageHead('ACCESS','One link for the user.<br>Clear control for you.','A subscription updates the node list. VPN access is managed separately.',`<button class="btn primary" data-act="add-user">${icon('plus')}Grant access</button>`)+`<div class="callout">${icon('link')} After replacing a node, publish the current profiles. The user refreshes the same subscription; their UUID stays unchanged.</div><section class="panel"><div class="table-head"><h2>Fleet access <span class="secondary">${state.userCount} users</span></h2>${pill('All enabled servers','blue')}</div><div class="table-wrap"><table><thead><tr><th>User</th><th>VPN access</th><th>Quota per server</th><th>Expiry</th><th>Subscription</th><th>Actions</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="access-person"><span class="access-avatar">${esc(u.name.slice(0,1).toUpperCase())}</span><span class="mono">${esc(u.name)}</span></div></td><td>${pill('Active','ok')}</td><td class="mono muted">${esc(u.quota)}</td><td class="muted">${esc(u.expiry)}</td><td>${pill(u.delivery==='published'?'Published':u.delivery==='revoked'?'Revoked':'Needs publishing',u.delivery==='published'?'ok':u.delivery==='revoked'?'neutral':'warn')}</td><td><div class="link-actions"><button class="text-link" data-act="${u.delivery==='revoked'?'rotate-user':'publish-user'}" data-id="${esc(u.name)}">${u.delivery==='published'?'Refresh':u.delivery==='revoked'?'New URL':'Publish'}</button><button class="icon-btn" data-act="access-detail" data-id="${esc(u.name)}" aria-label="Subscription settings ${esc(u.name)}">${icon('chevron')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="measure-note">Showing ${state.users.length} sample records. Quotas apply separately on each server.</div></section>`; }
function renderChecks() { main.innerHTML=pageHead('ACCESS CHECKS','Healthy services can still hide a broken route.','Check the path from a specific source to an HTTPS target.',checkButton())+`<div class="toolbar"><div class="filter-list"><button class="filter ${state.vantage==='local'?'active':''}" data-act="vantage" data-id="local">This device</button><button class="filter ${state.vantage==='remote'?'active':''}" data-act="vantage" data-id="remote">Remote checker</button></div>${pill(state.checking?'Check running':state.checkAge,state.checking?'blue':'neutral')}</div><section class="panel"><div class="check-summary">${icon('pulse')}<span>${state.vantage==='local'?'Checking from this device. The result applies to this network path.':'A separate, always-on checker. Its result may differ from your local network.'}</span></div><div class="table-wrap"><table><thead><tr><th>Ingress</th><th>Agent / Xray</th><th>HTTPS / TCP</th><th>UDP / DNS</th><th>Latest result</th></tr></thead><tbody>${state.nodes.map(n=>`<tr class="clickable" data-act="node" data-id="${esc(n.id)}" tabindex="0"><td class="mono">${esc(n.id)}</td><td><span class="checkmark">${icon('check')}Reachable</span></td><td>${bad(n)?pill('Failed','warn'):pill(`HTTP 200 · ${n.latency||49} ms`,'ok')}</td><td>${pill('Not checked')}</td><td><button class="text-link" data-act="${bad(n)?'incident':'node'}" data-id="${esc(n.id)}">${bad(n)?'Inspect evidence':'Details'} ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="measure-note">HTTPS check time is not RTT. UDP, DNS and app imports need separate tests. No fresh sample means no confirmation of current access.</div></section><div class="detail-grid" style="margin-top:22px"><section class="detail-tile"><small>On-demand check</small><strong>Native probe</strong><p class="help-line">One HTTPS request through the selected ingress, using a dedicated monitoring profile.</p></section><section class="detail-tile"><small>Continuous monitoring</small><strong>External checker</strong><p class="help-line">Receives client profiles only. It does not need SSH keys or the control database.</p></section></div>`; }
function renderChanges() { main.innerHTML=pageHead('CHANGE HISTORY','Every change has a clear trail.','Plan, scope, saved state and verified outcome, all in one operation.')+`<section class="panel"><div class="table-head"><h2>Recent operations</h2>${pill('Sample history','blue')}</div><div class="timeline">${state.jobs.map(j=>`<article class="timeline-row"><span class="event-icon">${icon('check')}</span><div><h3>${esc(j.title)}</h3><p>${esc(j.detail)}</p><div class="mono">${esc(j.id)} · completed · demonstration only</div></div><button class="btn" data-act="job" data-id="${esc(j.id)}">Result ${icon('chevron')}</button></article>`).join('')}</div></section><div class="callout">Applied and verified are different states. After a lost connection, reconcile the server before choosing recovery.</div>`; }
function renderBackups() { main.innerHTML=pageHead('RECOVERY','A backup should bring control back.','A runtime snapshot and a local workspace backup serve different recovery needs.',`<button class="btn primary" data-act="backup">${icon('shield')}Create snapshot</button>`)+`<div class="detail-grid"><section class="panel" style="padding:25px"><div class="eyebrow">RUNTIME</div><h2>Server configuration</h2><p class="help-line">Latest snapshot: 15 minutes ago.<br>Checksum and database integrity verified.</p>${pill('Archive verified','ok')}<button class="btn wide-button" data-act="restore-plan">Open recovery plan ${icon('arrow')}</button></section><section class="panel" style="padding:25px"><div class="eyebrow">CONTROL STATE</div><h2>Local workspace</h2><p class="help-line">Inventory, secret references and operation history.<br>Recovery is tested in an isolated environment.</p>${pill('Rehearsal planned','neutral')}<button class="btn wide-button" data-act="rehearsal">View rehearsal steps ${icon('arrow')}</button></section></div><div class="callout warn">A valid checksum confirms archive integrity. A successful restore still needs its own evidence.</div>`; }
function render() { nav(); ({overview:renderOverview,servers:renderServers,access:renderAccess,checks:renderChecks,changes:renderChanges,backups:renderBackups}[state.view]||renderOverview)(); }
function go(view) { if(state.view===view) render(); else location.hash=view; }
function dialogHead(id,title,description='',sheet=false) { return `<div class="dialog-head"><div><h2 id="${id}">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-btn" data-act="${sheet?'close-drawer':'close-modal'}" aria-label="Close">${icon('close')}</button></div>`; }
function showModal(html) { if(drawer.open) drawer.close(); modal.innerHTML=html; if(!modal.open) modal.showModal(); }
function showNode(id,incident=false) {
  const n=state.nodes.find(n=>n.id===id); if(!n)return;
  const issue=localBad(n);
  drawer.innerHTML=dialogHead('drawer-title',incident?'Services respond.<br>HTTPS failed.':esc(n.id),`${esc(n.role)} · ${esc(n.profile)} · sample data`,true)+`<div class="dialog-body"><div class="badge-row">${pill('SSH reachable','ok')}${pill('Xray running','ok')}${pill(issue?'HTTPS: failed':'HTTPS: HTTP 200',issue?'warn':'ok')}</div><div class="section-label">Verified evidence</div><div class="evidence">${icon('check')}<span><strong>Server management is reachable</strong><small>SSH and ovpn-agent respond.</small></span></div><div class="evidence">${icon('check')}<span><strong>Xray process is running</strong><small>This does not yet verify user traffic.</small></span></div><div class="evidence ${issue?'warn':''}">${icon(issue?'alert':'check')}<span><strong>${issue?'HTTPS did not complete':'HTTPS through the tunnel passed'}</strong><small>${issue?'Native probe and checker reported a failure.':'HTTP 200, certificate verified.'}</small></span>${pill(issue?'EOF':`${n.latency||49} ms`,issue?'warn':'ok')}</div><div class="section-label">Context</div><div class="plan-line"><span>Measured from</span><strong>This device</strong></div><div class="plan-line"><span>Freshness</span><strong>${state.checkAge}</strong></div><div class="plan-line"><span>Agent version</span><strong class="mono">${esc(n.version)}</strong></div><div class="plan-line"><span>UDP / DNS / GUI import</span><strong>Not checked</strong></div>${issue?`<div class="callout warn">Compare the agent version and the runtime user settings in Xray. A failed request alone does not establish the cause.</div><button class="btn primary wide-button" data-act="repair-plan">Prepare diagnostic plan ${icon('arrow')}</button>`:`<div class="callout">Success applies to this path and measurement time. Other network paths need their own checks.</div>`}<details style="margin-top:22px"><summary class="muted" style="font-size:11px;cursor:pointer">CLI command for a manual check</summary><pre class="code">ovpn user probe --server ${esc(n.id)} \\\n  --username monitor --json</pre></details></div>`;
  drawer.showModal();
}
function showWizard(step=0) {
  const titles=['Connect your server','Choose a clear starting point','Review what will change'];
  let content='';
  if(step===0) content=`<form id="server-form"><div class="form-row"><label class="field"><span>Server alias</span><input id="server-alias" required pattern="[a-z0-9-]{2,24}" value="${esc(wizard.alias||'edge-c')}" autocomplete="off"><small>A short name that is easy to recognize.</small></label><label class="field"><span>Server address</span><input id="server-host" required pattern="[A-Za-z0-9.:-]+" value="${esc(wizard.host||'edge-c.example.net')}" autocomplete="off"><small>The prototype never sends this address anywhere.</small></label></div><div class="form-row"><label class="field"><span>SSH user</span><input id="server-user" required pattern="[A-Za-z_][A-Za-z0-9_-]*" value="root" autocomplete="off"></label><label class="field"><span>SSH port</span><input id="server-port" type="number" min="1" max="65535" value="22" required></label></div><label class="field"><span>Authentication</span><select><option>Key from SSH agent</option><option>Choose a key file in the app</option></select><small>Keys and passphrases are handled by the native host.</small></label></form><div class="callout">First check connectivity and the host fingerprint. Setup starts after you review the plan.</div>`;
  if(step===1) content=`<div class="badge-row">${pill('SSH check: demonstration','blue')}</div><div class="callout"><strong>Host fingerprint</strong><br><span class="mono">SHA256:DEMO-EXAMPLE-NOT-A-REAL-HOST-KEY</span></div><label class="option-row"><input type="checkbox" id="trust-host" ${wizard.trusted?'checked':''}>I verified the host fingerprint (demo)</label><div class="section-label">Which profile should we use?</div><button class="choice ${wizard.profile!=='TLS'?'selected':''}" data-act="choose-profile" data-id="REALITY"><strong>VLESS + REALITY / TCP ${pill('Recommended','blue')}</strong><p>The OVPN baseline. Only the essential settings.</p></button><button class="choice ${wizard.profile==='TLS'?'selected':''}" data-act="choose-profile" data-id="TLS"><strong>VLESS + TLS / TCP</strong><p>Requires a domain and a valid certificate. Includes an HTTPS fallback site.</p></button><details><summary class="quiet" style="font-size:11px;cursor:pointer">Advanced settings</summary><p class="help-line">Fingerprint: Firefox. Target: your own HTTPS endpoint. Experimental transports are enabled separately after the baseline is verified.</p></details>`;
  if(step===2) content=`${planLines([['Server',wizard.alias],['Address',wizard.host],['SSH',`${wizard.sshUser||'root'} · port ${wizard.sshPort||22}`],['Profile',wizard.profile==='TLS'?'TLS / TCP':'REALITY / TCP'],['Scope','New node only'],['Existing users',`${state.userCount} · will be synchronized`],['Public transport','443 / TCP'],['Result verification','HTTPS through the new ingress']])}<div class="callout">Existing runtime state is saved before changes. A clean server is recorded as having no runtime yet.</div><div class="badge-row">${pill('1 server','blue')}${pill('No UUID rotation','ok')}${pill('Still a demo')}</div>`;
  showModal(dialogHead('modal-title',titles[step],'New server · guided setup')+`<div class="dialog-body"><div class="steps">${['01 · Connection','02 · Profile','03 · Plan'].map((s,i)=>`<span class="step ${i===step?'current':''}">${s}</span>`).join('')}</div>${content}</div><div class="dialog-foot"><button class="btn text" data-act="${step?'wizard-back':'close-modal'}" data-id="${step-1}">${step?'Back':'Cancel'}</button><button class="btn primary" data-act="wizard-next" data-id="${step}">${step===0?'Test connection (demo)':step===1?'Review plan':'Deploy in demo'}${icon('arrow')}</button></div>`);
}
function planLines(items) { return items.map(([key,value])=>`<div class="plan-line"><span>${esc(key)}</span><strong>${esc(value)}</strong></div>`).join(''); }
function showRepairPlan() { pendingPlan={kind:'repair'}; showModal(dialogHead('modal-title','A change with a verifiable outcome','Plan chg-042 · demonstration scenario')+`<div class="dialog-body">${pill('Runtime drift needs verification','warn')}<div class="callout">Compare saved configuration and runtime first. If missing Vision flow is confirmed, update only the agent and verify a new test identity.</div>${planLines([['Scope','1 server · edge-b'],['Agent','1.11.2 → 1.12.0'],['Existing UUIDs','Preserve'],['Xray process','Keep running'],['Before the change','Verified snapshot and previous binary'],['After the change','Native probe + checker'],['On failure','Reconcile state and offer rollback']])}<p class="help-line">This is a proposed workflow. All steps and outcomes in the prototype are simulated.</p></div><div class="dialog-foot"><small>No server commands are run</small><button class="btn primary" data-act="apply-plan">Apply in demo ${icon('arrow')}</button></div>`); }
function startOperation(kind, title, onDone) {
  if(running)return; running=true; let step=0;
  const labels=['Plan and scope checked','Initial state saved','Change applied','HTTPS and access verified','Outcome recorded'];
  function progress(){ const open=modal.open; modal.innerHTML=dialogHead('modal-title',title,'Simulated operation · no real commands are executed')+`<div class="dialog-body">${labels.map((label,i)=>`<div class="progress-step ${i<step?'done':i===step?'running':''}"><span class="state-icon">${i<step?'✓':String(i+1).padStart(2,'0')}</span>${label}<small>${i<step?'done':i===step?'now':''}</small></div>`).join('')}</div><div class="dialog-foot"><small>You can close this window; the simulation will continue.</small><button class="btn" data-act="close-modal">Minimize</button></div>`; if(!open&&step===0)modal.showModal(); }
  progress();
  const timer=setInterval(()=>{step++; if(step<labels.length){progress();return;} clearInterval(timer); running=false; onDone(); render(); if(modal.open)showModal(dialogHead('modal-title','Outcome verified','Simulation completed')+`<div class="dialog-body"><div class="success-body"><div class="success-orbit">${icon('check')}</div><h3>${kind==='add'?'The server is ready for access delivery.':'The change passed verification.'}</h3><p>HTTPS passed. Existing identities were preserved.</p></div>${pill('Sample data only','blue')}</div><div class="dialog-foot"><small>The outcome is available in history</small><button class="btn primary" data-act="close-modal">Done</button></div>`); else toast('Simulation finished. The outcome is in history.');},450);
}
function userForm(){if(!state.nodes.length){toast('Add a server before granting access.');return;}showModal(dialogHead('modal-title','Grant access','Review scope before creating an identity')+`<div class="dialog-body"><form id="user-form"><label class="field"><span>Username</span><input id="new-username" required pattern="[a-zA-Z0-9_-]{2,24}" value="new-user" autocomplete="off"></label><div class="form-row"><label class="field"><span>Access expiry</span><select id="new-expiry"><option value="30 days left">30 days</option><option value="No expiry">No expiry</option></select></label><label class="field"><span>Quota on each server</span><select id="new-quota"><option value="300 GB">300 GB / 30 days</option><option value="50 GB">50 GB / 30 days</option></select></label></div></form><div class="callout warn" id="quota-impact">This affects all ${state.nodes.length} enabled servers. The quota of 300 GB applies to each server separately.</div>${planLines([['New identity','1 user'],['Existing users','Unchanged'],['Delivery','Publish a subscription after creation']])}</div><div class="dialog-foot"><button class="btn text" data-act="close-modal">Cancel</button><button class="btn primary" data-act="create-user">Create in demo ${icon('arrow')}</button></div>`);}
function accessDetail(name){const u=state.users.find(u=>u.name===name);if(!u)return;showModal(dialogHead('modal-title',`Subscription ${esc(name)}`,'Configuration delivery and VPN access are separate')+`<div class="dialog-body"><div class="badge-row">${pill('VPN: active','ok')}${pill(u.delivery==='revoked'?'Subscription revoked':u.delivery==='stale'?'Needs publishing':'Subscription available',u.delivery==='revoked'?'neutral':u.delivery==='stale'?'warn':'blue')}</div><div class="callout">${u.delivery==='stale'?'No subscription snapshot has been published yet. Publish the current profiles to prepare delivery.':u.delivery==='revoked'?'Delivery has been revoked. Create a new URL to deliver configurations again. Imported VPN profiles remain active.':'The existing URL token is not stored. Rotate it to issue a new URL; the old URL will stop downloading configurations.'}</div>${planLines([['Scope',`${state.nodes.length} servers`],['User UUID','Unchanged'],['Previously imported profiles','Remain active']])}<button class="btn wide-button" data-act="${u.delivery==='stale'?'publish-user':'rotate-user'}" data-id="${esc(name)}">${u.delivery==='stale'?'Publish subscription (demo)':u.delivery==='revoked'?'Create a new URL (demo)':'Rotate URL (demo)'} ${icon('link')}</button>${u.delivery==='published'?`<button class="btn danger wide-button" data-act="revoke-user" data-id="${esc(name)}">Revoke subscription only</button>`:''}</div><div class="dialog-foot"><small>Revoking VPN access requires a separate operation.</small><button class="btn" data-act="close-modal">Close</button></div>`);}
function showCommand(){showModal(`<h2 id="modal-title" class="visually-hidden">Search actions</h2><div class="command-box">${icon('search')}<input id="command-input" placeholder="Server, screen or action…" aria-label="Search actions" autocomplete="off"><kbd>Esc</kbd></div><div class="command-results" id="command-results"></div>`);renderCommands('');$('#command-input').focus();}
function renderCommands(query){ const commands=[...navItems.map(n=>({text:n.label,act:'goto-'+n.id,icon:n.icon})),{text:'Add server',act:'add-server',icon:'plus'},{text:'Check access',act:'run-checks',icon:'pulse'},{text:'Grant access',act:'add-user',icon:'users'},{text:'Switch theme',act:'theme',icon:'sun'},{text:'Settings',act:'settings',icon:'grid'}];$('#command-results').innerHTML=commands.filter(c=>c.text.toLowerCase().includes(query.toLowerCase())).map(c=>`<button class="command-item" data-act="${c.act}">${icon(c.icon)}${c.text}<span class="tiny">↵</span></button>`).join('')||'<div class="empty">No matches</div>'; }
function jobDetail(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;showModal(dialogHead('modal-title',esc(j.title),`${esc(j.id)} · sample history`)+`<div class="dialog-body">${pill('Outcome verified','ok')}<p class="help-line">${esc(j.detail)}</p>${planLines([['Outcome','Simulation completed'],['Initial state','Saved'],['Existing users','Preserved'],['Evidence','Structured verification result']])}${j.kind==='repair'?'<button class="btn wide-button" data-act="rollback-plan">Review rollback plan</button>':''}</div><div class="dialog-foot"><small>All records are synthetic</small><button class="btn" data-act="close-modal">Close</button></div>`);}
function viewWorkspace(){if(running||state.checking){toast('Wait for the current demo operation to finish.');return;}showModal(dialogHead('modal-title','Explore two scenarios','This only changes the prototype’s sample data')+`<div class="dialog-body"><button class="choice" data-act="workspace-demo"><strong>Working fleet</strong><p>Four nodes, subscriptions and one traffic issue.</p></button><button class="choice" data-act="workspace-empty"><strong>First run</strong><p>Start with an empty workspace and add your first server.</p></button></div><div class="dialog-foot"><small>Nothing is written to OVPN</small><button class="btn" data-act="close-modal">Close</button></div>`);}
function showSettings(){showModal(dialogHead('modal-title','Settings','Language and appearance')+`<div class="dialog-body"><label class="field"><span>Application language</span><select id="app-language"><option value="en" ${OVPNLocale.language==='en'?'selected':''}>English</option><option value="ru" ${OVPNLocale.language==='ru'?'selected':''}>Russian</option></select><small>English is the default. Russian is available here.</small></label><label class="field"><span>Color theme</span><select id="app-theme"><option value="dark" ${document.documentElement.dataset.theme==='dark'?'selected':''}>Dark</option><option value="light" ${document.documentElement.dataset.theme==='light'?'selected':''}>Light</option></select></label><div class="callout">Preferences in this prototype last until the page is reloaded.</div></div><div class="dialog-foot"><small>Apply to the whole interface</small><button class="btn primary" data-act="close-modal">Done</button></div>`);}
const actions={
  settings:showSettings,
  theme(){const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('#theme-label').textContent=light?'Dark theme':'Light theme';},
  command:showCommand,workspace:viewWorkspace,
  'workspace-demo'(){clearTimeout(toast.timer);$('#toast').classList.remove('show');$('#toast').textContent='';state.vantage='local';state.filter='all';state.search='';state.nodes=initialNodes();state.users=initialUsers();state.userCount=24;state.fixed=false;state.jobs=initialJobs();modal.close();go('overview');},
  'workspace-empty'(){clearTimeout(toast.timer);$('#toast').classList.remove('show');$('#toast').textContent='';state.vantage='local';state.filter='all';state.search='';state.nodes=[];state.users=[];state.userCount=0;state.fixed=true;state.jobs=[];modal.close();go('overview');},
  'close-modal'(){modal.close();},'close-drawer'(){drawer.close();},
  node(id){showNode(id);},incident(){showNode('edge-b',true);},
  'add-server'(){wizard={alias:'edge-c',host:'edge-c.example.net',profile:'REALITY',trusted:false};showWizard(0);},
  'wizard-back'(id){showWizard(Number(id));},
  'choose-profile'(id){wizard.trusted=$('#trust-host')?.checked;wizard.profile=id;showWizard(1);},
  'wizard-next'(id){const step=Number(id);if(step===0){const form=$('#server-form');const field=$('#server-alias');field.setCustomValidity(OVPNLocale.text(state.nodes.some(n=>n.id===field.value)?'This alias is already in use':''));if(!form.reportValidity())return;wizard.alias=field.value;wizard.host=$('#server-host').value;wizard.sshUser=$('#server-user').value;wizard.sshPort=$('#server-port').value;showWizard(1);}else if(step===1){if(!$('#trust-host').checked){toast('Verify the host fingerprint before continuing.');return;}wizard.trusted=true;showWizard(2);}else{const data={...wizard};startOperation('add',`Setting up ${esc(data.alias)}`,()=>{state.nodes.push({id:data.alias,role:'New ingress',profile:data.profile==='TLS'?'TLS / TCP':'REALITY / TCP',latency:49,version:'1.12.0'});state.jobs.unshift({id:'chg-'+String(42+state.jobs.length),title:`Added server ${data.alias}`,detail:'Plan completed and HTTPS verified. Publish updated subscriptions separately.',kind:'add'});});}},
  'repair-plan':showRepairPlan,
  'apply-plan'(){if(pendingPlan?.kind!=='repair')return;startOperation('repair','Checking and updating edge-b',()=>{state.fixed=true;const n=state.nodes.find(n=>n.id==='edge-b');if(n){n.version='1.12.0';n.latency=63;}state.jobs.unshift({id:'chg-042',title:'edge-b: access restored',detail:'Agent updated. Native probe and checker returned HTTP 200. UUIDs preserved.',kind:'repair'});});},
  'run-checks'(){if(state.checking)return;if(modal.open)modal.close();state.checking=true;render();setTimeout(()=>{state.checking=false;state.checkAge='just now';render();toast('Demo check finished. Results updated.');},1100);},
  filter(id){state.filter=id;renderServers();},vantage(id){state.vantage=id;renderChecks();},
  'add-user':userForm,
  'create-user'(){const field=$('#new-username');field.setCustomValidity(OVPNLocale.text(state.users.some(u=>u.name===field.value)?'This alias is already in use':''));if(!$('#user-form').reportValidity())return;state.users.unshift({name:field.value,quota:$('#new-quota').value,expiry:$('#new-expiry').value,delivery:'stale'});state.userCount++;modal.close();go('access');toast('Sample user created. Subscription needs publishing.');},
  'publish-user'(name){const u=state.users.find(u=>u.name===name);if(!u)return;if(u.delivery!=='published'){actions['rotate-user'](name);return;}u.delivery='published';if(modal.open)modal.close();state.jobs.unshift({id:'pub-'+state.jobs.length,title:`Published subscription for ${name}`,detail:'Profiles updated. URL and UUIDs remain unchanged.',kind:'publish'});render();toast('Demo: profiles published through the existing URL.');},
  'access-detail':accessDetail,
  'revoke-user'(name){const u=state.users.find(u=>u.name===name);if(!u)return;showModal(dialogHead('modal-title','Revoke subscription delivery?',`User ${esc(name)} will retain previously imported VPN access`)+`<div class="dialog-body"><div class="callout warn">New configuration downloads will stop. The user’s UUID and VPN access remain unchanged.</div></div><div class="dialog-foot"><button class="btn" data-act="close-modal">Cancel</button><button class="btn danger" data-act="confirm-revoke" data-id="${esc(name)}">Revoke in demo</button></div>`);},
  'confirm-revoke'(name){const u=state.users.find(u=>u.name===name);if(u)u.delivery='revoked';modal.close();render();toast('Subscription revoked. VPN profiles remain active.');},
  'rotate-user'(name){const u=state.users.find(u=>u.name===name);if(!u)return;const rotation=u.delivery==='published';u.delivery='published';state.jobs.unshift({id:'delivery-'+state.jobs.length,title:rotation?'Subscription URL rotated':'New subscription URL created',detail:'A new delivery token is issued. VPN UUIDs remain unchanged.',kind:'publish'});showModal(dialogHead('modal-title','A new URL is shown once','Demonstration only · grants no actual access')+`<div class="dialog-body"><label class="field"><span>Personal subscription URL</span><input readonly value="https://subscriptions.example.net/sub/DEMO/EXAMPLE-NOT-A-VALID-TOKEN"></label><div class="callout">${rotation?'In the application, the new token is shown once. The previous URL stops updating; VPN access remains active.':'The new subscription URL is shown once. Save it before closing. VPN UUIDs remain unchanged.'}</div></div><div class="dialog-foot"><small>An example, not a secret token</small><button class="btn primary" data-act="close-modal">Got it</button></div>`);render();},
  job:jobDetail,
  backup(){state.jobs.unshift({id:'backup-'+state.jobs.length,title:'Created sample runtime snapshot',detail:'Checksum and database integrity verified. A restore rehearsal has not been completed yet.',kind:'backup'});render();toast('Demo snapshot saved in history.');},
  'restore-plan'(){showModal(dialogHead('modal-title','Runtime recovery plan','Verify the archive and scope first')+`<div class="dialog-body">${planLines([['Selected snapshot','15 minutes ago'],['Integrity','Verified'],['Scope','One selected server'],['Identities','Compare before and after'],['Completion','HTTPS and a fresh tunneled session']])}<div class="callout warn">Existing TCP sessions may drop during runtime recovery. Verify success with a fresh connection.</div></div><div class="dialog-foot"><small>Plan preview; no operation is started</small><button class="btn" data-act="close-modal">Close</button></div>`);},
  rehearsal(){showModal(dialogHead('modal-title','Recovery rehearsal','Isolated environment and synthetic identities')+`<div class="dialog-body">${planLines([['1. Verify','Archive integrity and decryption'],['2. Restore','A workspace copy'],['3. Connect','A test node'],['4. Verify','Tunnel traffic and test credential revocation'],['5. Preserve','A report without secrets']])}<div class="callout">This workflow is proposed separately. It does not restore production configuration.</div></div><div class="dialog-foot"><button class="btn" data-act="close-modal">Close</button></div>`);},
  'rollback-plan'(){showModal(dialogHead('modal-title','Rollback needs verification too','Restore the previous agent binary')+`<div class="dialog-body">${planLines([['Artifact','Saved binary from before the change'],['Xray and UUIDs','Preserved'],['Verification','Health, runtime and HTTPS'],['Limit','The previous issue may return']])}<div class="callout warn">A restart alone does not verify rollback. A fresh check is required.</div></div><div class="dialog-foot"><small>Proposed operation preview</small><button class="btn" data-act="close-modal">Go back</button></div>`);}
};
document.addEventListener('click', event=>{const button=event.target.closest('[data-act]');if(!button||button.disabled)return;const act=button.dataset.act;if(act.startsWith('goto-')){if(modal.open)modal.close();go(act.slice(5));return;}actions[act]?.(button.dataset.id);});
document.addEventListener('input',event=>{if(event.target.id==='node-search'){state.search=event.target.value;$('#node-rows').innerHTML=nodeRows(filteredNodes());}if(event.target.id==='command-input')renderCommands(event.target.value);});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showCommand();return;}if(event.key==='Enter'&&event.target.matches('tr[data-act]'))actions[event.target.dataset.act]?.(event.target.dataset.id);if(event.key==='Enter'&&event.target.id==='command-input')$('#command-results button')?.click();});
document.addEventListener('change',event=>{if(event.target.id==='app-language')OVPNLocale.set(event.target.value);if(event.target.id==='app-theme'){document.documentElement.dataset.theme=event.target.value;$('#theme-label').textContent=event.target.value==='light'?'Dark theme':'Light theme';}if(event.target.id==='new-quota')$('#quota-impact').textContent=`This affects all ${state.nodes.length} enabled servers. The quota of ${event.target.value} applies to each server separately.`;});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);state.view=navItems.some(n=>n.id===view)?view:'overview';render();main.focus({preventScroll:true});window.scrollTo(0,0);});
state.view=navItems.some(n=>n.id===location.hash.slice(1))?location.hash.slice(1):'overview';
render();
